"""Generate health_fold.json: what the pipeline's health retention did to a set of rows.

The fold of raw health_samples into 10-minute rollups (and the 30-day rollup prune)
moved from the workers' pruner (pipeline engine/prune.py) to the hub's cache
(api/internal/cluster/cache). This runs the Python code on a SQLite database built from
the shipped migrations, so the Go port can be checked against it (fold_test.go).

Run from pipeline/ (it imports the pipeline and its test helpers), with the prune.py that
still folds (before track T5 removed it):

    uv run --extra dev python ../api/internal/cluster/cache/testdata/gen_health_fold.py
"""

from __future__ import annotations

import asyncio
import json
import sqlite3
import sys
import tempfile
from datetime import UTC, datetime, timedelta
from pathlib import Path

sys.path.insert(0, str(Path.cwd()))

from maktaba_pipeline.engine.prune import prune_once  # noqa: E402
from maktaba_pipeline.engine.sql import parse_ts, to_ts  # noqa: E402
from maktaba_pipeline.runtime import Database  # noqa: E402
from tests.engine.migrate import apply_sqlite  # noqa: E402

NOW = datetime(2026, 10, 19, 12, 34, 56, 789000, tzinfo=UTC)
OUT = Path(__file__).resolve().parent / "health_fold.json"


def rows() -> list[tuple[datetime, str, str, float]]:
    """Raw samples from 50 h to 47 h ago (every 211 s, three hosts, four metrics, values
    with fractions) and a few recent ones, the 48 h edge's neighbours, and rollups: one
    31 days old (pruned), one 29 days old (kept), one for a bucket the fold rewrites."""
    out: list[tuple[datetime, str, str, float]] = []
    start = NOW - timedelta(hours=50)
    metrics = ("cpu.pct", "nas.timeouts", "nas.open_ms_p95", "stt.audio_sec:mlx-0")
    times: list[datetime] = []
    t = start
    while t < NOW - timedelta(hours=47):
        times.append(t)
        t += timedelta(seconds=211)
    t = NOW - timedelta(minutes=5)
    while t < NOW:
        times.append(t)
        t += timedelta(seconds=60)
    for i, t in enumerate(times):
        for h, host in enumerate(("studio", "linux-box", "win-pc")):
            for m, metric in enumerate(metrics):
                if (i + h + m) % 5 == 0:
                    continue  # not every host reports every metric every time
                value = round(((i * 7 + h * 13 + m * 3) % 97) * 1.37 + 0.1 * h, 3)
                out.append((t + timedelta(milliseconds=h * 101 + m), host, metric, value))
    edge = (NOW - timedelta(hours=48)).replace(second=0, microsecond=0)
    edge = edge.replace(minute=edge.minute - edge.minute % 10)
    for d, v in ((-timedelta(milliseconds=1), 11.5), (timedelta(0), 22.25), (timedelta(seconds=1), 33.0)):
        out.append((edge + d, "edge-host", "cpu.pct", v))
    out.append((NOW - timedelta(days=31), "*rollup*", "cpu.pct", 1.0))
    out.append((NOW - timedelta(days=29), "*rollup*", "cpu.pct", 2.0))
    rewritten = (NOW - timedelta(hours=49)).replace(second=0, microsecond=0)
    rewritten = rewritten.replace(minute=rewritten.minute - rewritten.minute % 10)
    out.append((rewritten, "*rollup*", "cpu.pct", 999.0))
    return out


def iso(t: datetime) -> str:
    return t.astimezone(UTC).strftime("%Y-%m-%dT%H:%M:%S.") + f"{t.microsecond // 1000:03d}Z"


async def main() -> None:
    with tempfile.TemporaryDirectory() as tmp:
        path = Path(tmp) / "fold.db"
        conn = sqlite3.connect(path)
        apply_sqlite(conn)
        conn.close()
        db = await Database.connect(f"sqlite:///{path}")
        try:
            seeded = rows()
            for at, host, metric, value in seeded:
                await db.execute(
                    "INSERT INTO health_samples (at, host, metric, value) VALUES ($1,$2,$3,$4)",
                    to_ts(db, at),
                    host,
                    metric,
                    value,
                )
            report = await prune_once(db, at=NOW)
            after = await db.fetch(
                "SELECT at, host, metric, value FROM health_samples ORDER BY metric, host, at"
            )
        finally:
            await db.close()
    def lines(rs: list[list[object]]) -> str:
        return ",\n".join(json.dumps(r) for r in rs)

    inp = [[iso(at), host, metric, value] for at, host, metric, value in seeded]
    out = [[iso(parse_ts(r["at"]) or NOW), r["host"], r["metric"], float(r["value"])] for r in after]
    doc = "Generated by gen_health_fold.py from pipeline engine/prune.py (prune_once on SQLite)."
    OUT.write_text(
        "{\n"
        f'"_doc": {json.dumps(doc)},\n'
        f'"now": {json.dumps(iso(NOW))},\n'
        f'"folded": {report.health_samples},\n'
        f'"rollups_pruned": {report.health_rollups},\n'
        f'"input": [\n{lines(inp)}\n],\n'
        f'"output": [\n{lines(out)}\n]\n'
        "}\n",
        encoding="utf-8",
    )
    print(f"wrote {OUT}: {len(seeded)} rows in, {len(after)} out, {report}")


asyncio.run(main())
